import {cet} from './climate-data.js?v=20261023-weather03';
export const weatherViews2={
 'weather-greenhouse':[['natural','Natural greenhouse'],['enhanced','Enhanced greenhouse'],['compare','Energy balance']],
 'weather-sources':[['fuel','Fuel & industry'],['farming','Farming & methane'],['leaks','Fossil-fuel leaks'],['system','Whole system']],
 'weather-impacts':[['crops','Crop yields'],['sea','Sea-level process'],['glacier','Glacier retreat'],['people','People & exposure']],
 'weather-uk-history':[['millennium','Last millennium'],['line','1659–2025 line'],['bars','30-year bars'],['recent','Recent years'],['table','Accessible values']],
 'weather-uk-controls':[['setting','Atlantic setting'],['rain','Relief rainfall'],['latitude','Latitude & altitude'],['season','Coast & seasons']]
};
export const weatherRequirements2=Object.fromEntries(Object.entries(weatherViews2).map(([k,v])=>[k,v.map(x=>x[0])]));
export const weatherAnimated2=(k,v)=>k==='weather-greenhouse'?v!=='compare':k==='weather-sources'?v!=='system':k==='weather-impacts'?['sea','glacier'].includes(v):k==='weather-uk-controls'?['setting','rain'].includes(v):false;
const text=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const path=(d,c='#b8dce2',w=3,extra='')=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" ${extra}/>`;
const arrow=(x,y,a,b,c='#f3b49d')=>path(`M${x} ${y}L${a} ${b}`,c,3,'marker-end="url(#w2Arrow)"');
const circle=(x,y,r=6,c='#f3b49d')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
const box=(x,y,w,h,label)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="10" fill="#365368" stroke="#a3bbc6"/>`+text(x+12,y+27,label);
const svg=(b,label)=>`<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${label.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><defs><marker id="w2Arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5 0 10Z" fill="#f3b49d"/></marker><linearGradient id="w2Sea" x2="0" y2="1"><stop stop-color="#85b7c9"/><stop offset="1" stop-color="#3e718a"/></linearGradient></defs><g fill="#edf2f2" font-family="sans-serif">${b}</g></svg>`;
const wrap=(b,c)=>svg(b,c)+`<p class="geo-caption">${c}</p>`;
const sourceNote=`Met Office HadCET v2.1.1.0 · Central England (Lancashire–London–Bristol triangle) · °C · complete years only · retrieved23October2026. <a href="https://www.metoffice.gov.uk/hadobs/hadcet/" target="_blank" rel="noopener">Source and method</a> · <a href="./geography/data/hadcet-seasonal-2026-10-23.txt" target="_blank" rel="noopener">Source values</a> · © Crown copyright, <a href="https://www.nationalarchives.gov.uk/doc/open-government-licence/version/3/" target="_blank" rel="noopener">OGL3.0</a>.`;
export function climateGraph(view='line'){
 if(view==='table')return `<table class="geo-data"><caption>HadCET · annual means (selected recent years) and selected30-year averages · °C</caption><thead><tr><th scope="col">Year / period</th><th scope="col">Mean °C</th></tr></thead><tbody>${[...cet.annual.filter(([y])=>y>=2016).map(([y,v])=>[y,v]),...cet.periods.map(p=>[p.from+'–'+p.to,p.mean])].map(([y,v])=>`<tr><th scope="row">${y}</th><td>${v.toFixed(2)}</td></tr>`).join('')}</tbody></table><p class="geo-caption">${sourceNote}</p>`;
 let b='',label='';
 if(view==='bars'){
  b=text(22,27,'CENTRAL ENGLAND · selected30-year means',14)+text(22,52,'Mean temperature (°C) · absolute, not anomaly',12);
  for(let y=0;y<=12;y+=3){const p=282-y*17;b+=path(`M48 ${p}H420`,'#7793a4',1)+text(15,p+4,''+y,12);}
  cet.periods.forEach((p,i)=>{const x=72+i*120,h=p.mean*17;b+=`<rect x="${x}" y="${282-h}" width="70" height="${h}" rx="4" fill="${i===2?'#f0ad96':'#a8ced6'}"/>`+text(x+13,272-h,p.mean.toFixed(2),14)+text(x-3,308,p.from+'–'+p.to,12);});
  b+=text(48,338,'Period · arithmetic mean of30 published annual means',11);label='Central England selected30-year mean temperatures: '+cet.periods.map(p=>p.from+'–'+p.to+' '+p.mean.toFixed(2)+'°C').join('; ')+'. Axis starts at0°C; gaps between selected periods are not proportional.';
 }else{
  const recent=view==='recent',rows=cet.annual.filter(([y])=>!recent||y>=2016),min=recent?9:6,max=12,from=rows[0][0],to=rows.at(-1)[0],X=y=>52+(y-from)/(to-from)*358,Y=v=>280-(v-min)/(max-min)*205;
  b=text(22,27,'CENTRAL ENGLAND · annual mean temperature',14)+text(22,52,'°C · '+from+'–'+to+' · vertical axis starts at'+min+'°C',12);
  for(let y=min;y<=max;y++){b+=path(`M52 ${Y(y)}H415`,'#7793a4',1)+text(20,Y(y)+4,''+y,12);}
  b+=path(rows.map(([y,v],i)=>(i?'L':'M')+X(y).toFixed(2)+' '+Y(v).toFixed(2)).join(' '),'#f1b39d',recent?3:1.5);
  for(const y of recent?[2016,2019,2022,2025]:[1659,1750,1850,1950,2025])b+=text(X(y)-14,305,''+y,11);
  if(recent)for(const [y,v]of rows){b+=circle(X(y),Y(v),3,'#f3c6b2');if([2021,2022,2025].includes(y))b+=text(X(y)-13,Y(v)-12,v.toFixed(2),11);}
  b+=text(200,333,'Year',12);label=`Central England annual mean temperatures ${from}–${to} in degrees Celsius. Vertical axis ${min}–12°C; joined annual observations, not a smoothed trend or global series.`;
 }
 const values=view==='bars'?cet.periods.map(p=>[p.from+'–'+p.to,p.mean]):cet.annual.filter(([y])=>view!=='recent'||y>=2016);
 const table=`<details class="geo-chart-values"><summary>Read chart values</summary><div style="max-height:350px;overflow:auto" tabindex="0" role="region" aria-label="Chart values table"><table class="geo-data"><caption>Same plotted Central England values · °C</caption><thead><tr><th scope="col">${view==='bars'?'Period':'Year'}</th><th scope="col">Mean °C</th></tr></thead><tbody>${values.map(([y,v])=>`<tr><th scope="row">${y}</th><td>${v.toFixed(2)}</td></tr>`).join('')}</tbody></table></div></details>`;
 return svg(b,label)+`<p class="geo-caption">${sourceNote}</p>`+table;
}
export function weatherScene2(k,selected,t=0){if(!weatherViews2[k])return '';const v=weatherViews2[k].some(x=>x[0]===selected)?selected:weatherViews2[k][0][0];t=Math.min(1,Math.max(0,Number(t)||0));if(!weatherAnimated2(k,v))t=0;let b='',c='';
 if(k==='weather-greenhouse'){
  if(v==='compare'){b=text(24,30,'CHANGE THE ENERGY BALANCE')+box(24,90,392,45,'Same incoming sunlight initially')+arrow(220,145,220,183)+box(24,193,392,45,'More greenhouse gases: less initial energy loss')+arrow(220,245,220,278)+text(55,312,'Energy accumulates → warming → more infrared',13);c='The enhanced greenhouse effect changes outgoing infrared energy transfer, not the Sun’s output. Warming increases infrared emission. This is a qualitative balance, with no measured fluxes.';}
  else{const more=v==='enhanced';b=text(24,30,more?'ENHANCED GREENHOUSE · energy pathways':'NATURAL GREENHOUSE · energy pathways')+'<path d="M20 292Q220 245 420 292V340H20Z" fill="#7e9d96"/><path d="M40 130Q220 75 400 130" fill="none" stroke="#a8c9d4" stroke-width="28" opacity=".35"/>'+circle(68,65,22,'#eacb8f')+arrow(80,90,160,270,'#f0d595')+arrow(225,265,225,120)+arrow(225,110,225,48)+arrow(253,126,310,258)+circle(80+80*t,90+180*t,6,'#f4dfac')+circle(225,265-200*t,6)+circle(253+57*t,126+132*t,6)+text(24,323,'Surface warms · infrared absorbed and emitted',12)+text(265,64,'Space: energy escapes',11)+text(25,185,'Sunlight',12)+text(268,180,'Infrared',12);for(let i=0;i<(more?13:6);i++)b+=circle(65+i*(more?26:57),115+Math.sin(i)*10,4,'#d8e6e8');if(more)b+=arrow(185,122,145,250)+circle(185-40*t,122+128*t,6);c='Sunlight warms the surface; outgoing infrared is partly absorbed and emitted in all directions by greenhouse gases. '+(more?'More gas reduces initial energy loss at the same surface temperature.':'The natural process already warms Earth.')+' Dots, gas spacing, timing and arrow counts are symbolic, not photon paths, measured amounts or a solid atmospheric lid. Some energy escapes.';}
 }
 if(k==='weather-sources'){
  if(v==='system'){b=text(24,30,'FOLLOW THE WHOLE SYSTEM')+box(25,80,170,65,'Electricity generation')+box(245,80,170,65,'Manufacturing')+arrow(110,155,175,235)+arrow(330,155,265,235)+box(145,245,160,50,'Vehicle use')+text(25,325,'No exhaust CO₂ ≠ zero lifecycle emissions',13);c='An electric vehicle has no exhaust CO₂ while driving. Generation, manufacture and fuel supply affect lifecycle emissions. No sector percentages or numerical footprint are shown.';}
  else{const farm=v==='farming',leak=v==='leaks',label=farm?'Livestock / manure / rice':leak?'Fossil-fuel production / transport':'Energy / transport / industry';b=text(24,30,label.toUpperCase(),14)+`<rect x="25" y="275" width="390" height="55" rx="10" fill="#738e89"/>`+(farm?'<path d="M65 220h95v45h-95zM70 265v25m70-25v25M150 220l25-12v38h-25" fill="#d7c4af" stroke="#d7c4af" stroke-width="7"/>':leak?path('M45 245H190V210H360','#a9cbd2',22)+path('M192 190l-15 25 28-5','#f2b49d',5):'<path d="M45 275V190l65 25v-25l65 25v60Z" fill="#a5b8c1"/><rect x="125" y="125" width="22" height="95" fill="#a5b8c1"/>')+arrow(200,220,285,95)+circle(200+85*t,220-125*t,9)+box(275,60,135,50,farm||leak?'CH₄ methane':'CO₂')+text(24,315,farm?'Multiple farming pathways; machinery also emits CO₂':leak?'Unburned methane leak, distinct from combustion':'Combustion; some industrial chemical processes',11);c=farm?'Livestock digestion, manure and flooded rice cultivation can emit methane; agricultural fuel use can also emit CO₂. Icons group mechanisms, not equal measured emissions.':leak?'Methane can escape during fossil-fuel production and transport. Leakage releases unburned methane; combustion emits CO₂. Moving dots indicate release, not a leak-rate measurement.':'Fossil-fuel burning in energy, transport and industry releases CO₂; industrial processes such as cement manufacture can also release CO₂. Routes are schematic; visible smoke is not a gas measurement.';}
 }
 if(k==='weather-impacts'){
  if(v==='crops'){b=text(24,30,'CROP RESPONSE DEPENDS ON CONDITIONS')+circle(360,90,25,'#e8c996')+'<path d="M30 280H410V325H30Z" fill="#8e9f8c"/>';for(let i=0;i<6;i++){const x=65+i*60,h=i<3?90:45;b+=path(`M${x} 280V${280-h}m0 18l-16-13m16 30l16-13`,'#c9d4a9',5);}b+=text(25,105,'Longer season may help',12)+text(25,132,'Heat / water stress can harm',12)+text(25,315,'Crop + location + water + adaptation',13);c='Illustrative contrasting crops, not measured yields: some places gain opportunities while heat, drought and extremes can reduce production and income. The drawing is not a forecast or a before/after photograph.';}
  else if(v==='sea'){const y=245-38*t;b=text(24,30,'WARMER OCEAN + LAND-ICE LOSS')+`<path d="M25 225L105 115 190 225V325H25Z" fill="#829997"/><path d="M74 160L105 115 142 177 120 166 103 179Z" fill="#dcebf1"/><path d="M190 ${y}H418V325H190Z" fill="url(#w2Sea)"/>`+path('M190 245H418','#e4e8d9',1,'stroke-dasharray="5 4"')+arrow(120,195,220,246)+circle(120+100*t,195+51*t,6,'#d3e8ed')+arrow(350,290,350,225)+text(226,180,'Mean sea level rises',13)+text(210,315,'Expansion + added water',12);c='Ocean warming causes thermal expansion; melting land ice adds water. Dashed line is the schematic starting sea level. Height and timing are exaggerated, not measured sea-level projections; floating sea ice is not the principal direct contribution shown.';}
  else if(v==='glacier'){const front=350-110*t;b=text(24,30,'RETREATING FRONT · ICE STILL FLOWS DOWNHILL')+'<path d="M20 90L125 165 260 240 420 290V330H20Z" fill="#849794"/>'+`<path d="M25 105Q90 110 150 155L${front} ${205+(front-240)*.35}L${front-8} ${229+(front-240)*.35}Q130 210 25 145Z" fill="#c8e2ea"/>`+arrow(100,155,205,211)+circle(100+105*t,155+56*t,6,'#40748d')+path(`M${front} 220V300`,'#f4baa5',2,'stroke-dasharray="5 4"')+text(210,320,'Front shifts uphill ←',13)+text(24,65,'Loss exceeds gain over time · not reverse ice flow',12);c='Sustained net ice loss moves the front back uphill while ice particles continue moving downslope. The loop resets a conceptual comparison; it is not an actual glacier record or a full mass-balance simulation.';}
  else{b=text(24,30,'PHYSICAL CHANGE → HUMAN CONSEQUENCES')+box(25,75,390,48,'Lower harvest → income / food-access risk')+box(25,150,390,48,'Sea-level rise → coastal flood exposure')+box(25,225,390,48,'Ice loss → altered seasonal water supply')+text(25,325,'Exposure, vulnerability and adaptation differ',13);c='Impacts depend on local exposure, vulnerability and adaptation. These are possible pathways, not equal risks, inevitable outcomes or numerical forecasts for all places.';}
 }
 if(k==='weather-uk-history'){
  if(v!=='millennium')return climateGraph(v);
  b=text(24,30,'UK LAST MILLENNIUM · QUALITATIVE CONTEXT')+box(25,75,390,45,'Medieval regional warm phase')+box(25,145,390,45,'Little Ice Age: regional cold phases')+box(25,215,390,45,'Recent warming: instrumental evidence')+text(25,303,'Before1659: proxy / documentary evidence needed',12)+text(25,330,'Boxes are not proportional durations or temperatures',12);c='North Atlantic regional warm and cold phases were not globally synchronous. Northwest Europe experienced especially cold conditions in the1600s. This qualitative context covers the last millennium; the separate HadCET thermometer graphs start1659 and cannot measure the earlier centuries.';
 }
 if(k==='weather-uk-controls'){
  if(v==='setting'){b=text(24,30,'ATLANTIC → UK · MID-LATITUDE WESTERLIES')+'<rect x="25" y="95" width="390" height="200" rx="18" fill="url(#w2Sea)"/><path d="M260 105L285 126 273 156 299 182 285 209 315 239 294 270 255 263 239 229 253 195 232 169 247 141Z" fill="#afc1aa"/>'+arrow(65,230,245,163)+circle(65+180*t,230-67*t,7,'#e8c6aa')+text(38,130,'Atlantic',16)+text(320,210,'UK',16)+text(25,330,'Southwesterly = from southwest · not every day',12);c='The UK lies in the mid-latitude westerlies beside the relatively warm Atlantic and near continental Europe. Maritime air and ocean influence moderate climate. Locator geometry is schematic, not a scaled weather map or a guarantee of daily wind direction.';}
  else if(v==='rain'){b=text(24,30,'WEST → EAST · RELIEF RAINFALL SECTION')+'<path d="M20 290L80 280 190 130 250 225 420 285V330H20Z" fill="#94a89a"/>'+arrow(35,230,170,130)+arrow(245,160,390,245)+circle(35+135*t,230-100*t,7,'#c5e0e7')+text(25,88,'Moist Atlantic air',13)+text(245,115,'Drier sheltered side',12);for(let i=0;i<5;i++)b+=path(`M${120+i*13} ${155+((t+i*.15)%1)*60}l-5 13`,'#a9d9ed',3);b+=text(25,325,'Rises → cools → condenses · not all UK rain is relief',12);c='Moist maritime air rising over western relief cools and may condense and rain; shelter contributes to drier eastern areas. Geometry and timing are symbolic. Frontal and convectional rainfall also occur, and wind direction varies.';}
  else if(v==='latitude'){b=text(24,30,'SEPARATE LATITUDE AND ALTITUDE')+box(25,75,390,50,'South → north: generally cooler')+'<path d="M65 280L215 145 365 280Z" fill="#8ea79c"/>'+arrow(240,260,240,170)+text(262,210,'Higher:',14)+text(262,232,'generally cooler',12)+text(25,330,'Compare places with other controls in mind',12);c='Higher latitude and higher altitude generally lower temperatures. Local exposure, air masses, maritime effects and season modify broad patterns; this schematic supplies no measured lapse rate or station normals.';}
  else{b=text(24,30,'COAST VS INLAND · GENERAL COMPARISON')+box(25,90,185,60,'Coast: ocean influence')+box(230,90,185,60,'Inland: less moderated')+text(25,205,'Milder winter tendency',13)+text(230,205,'Colder winter potential',13)+text(25,250,'Cooler summer tendency',13)+text(230,250,'Warmer summer potential',13)+text(25,325,'Latitude, altitude, winds and season still matter',12);c='Ocean influence often reduces coastal seasonal temperature range compared with inland areas. Winter and summer spatial contrasts can differ. These tendencies are conceptual, not a measured pair of stations or a forecast.';}
 }
 return wrap(b,c);
}
